from __future__ import annotations

import math
from numbers import Real


class JobqError(Exception):
    """Базовая ошибка пакета."""


class ConfigError(JobqError):
    """Некорректная конфигурация: часы, обработчики, параметры очереди."""


class InvalidJobError(JobqError):
    """Некорректные параметры постановки задания в очередь."""


class JobNotFoundError(JobqError):
    """Задание с таким идентификатором не найдено в хранилище."""

    def __init__(self, job_id: str) -> None:
        super().__init__(f"job {job_id!r} not found")
        self.job_id = job_id


class PermanentJobError(JobqError):
    """Обработчик сообщает, что повтор задания заведомо не поможет.

    Политика повторов не повторяет такое задание: оно сразу переходит в ``FAILED``.
    """


class RetryLaterError(JobqError):
    """Обработчик сообщает, через сколько секунд внешний сервис ждёт следующую попытку.

    Повтор планируется через ``min(retry_after, max_delay)`` секунд без джиттера.
    Ошибка остаётся временной: проверка повторяемости и лимит попыток действуют как обычно.
    """

    def __init__(self, message: str = "", *, retry_after: float) -> None:
        super().__init__(message)
        if isinstance(retry_after, bool) or not isinstance(retry_after, Real):
            raise ConfigError("retry_after must be a number")
        if not math.isfinite(retry_after):
            raise ConfigError("retry_after must be finite")
        if retry_after < 0:
            raise ConfigError("retry_after must be non-negative")
        self.retry_after = float(retry_after)


